import {createHash} from 'node:crypto';
import {readFile} from 'node:fs/promises';
const file='/workspace/apps/ssr-bench/dist/rivet-compiled.mjs';
const {renderPage}=await import(file);
const page={title:'Profile fixture',token:'profile',rows:Array.from({length:1000},(_,i)=>({id:String(i),values:Array.from({length:10},(_,j)=>`row-${i}-field-${j}`)}))};
const chunks=[];await renderPage(page,{}, {destroyed:false,writableEnded:false,write(s){chunks.push(s);return true;}});
const html=chunks.join('');
const sink={destroyed:false,writableEnded:false,units:0,write(s){this.units+=s.length;return true;}};
for(let i=0;i<200;i++)await renderPage(page,{},sink);
sink.units=0;
const cpu=process.cpuUsage();const start=performance.now();
for(let i=0;i<2000;i++)await renderPage(page,{},sink);
const wall=performance.now()-start;const used=process.cpuUsage(cpu);
console.log(JSON.stringify({renders:2000,rows:1000,cpuMs:(used.user+used.system)/1000,wallMs:wall,utf16UnitsWritten:sink.units,htmlSha256:createHash('sha256').update(html).digest('hex'),artifactSha256:createHash('sha256').update(await readFile(file)).digest('hex'),scope:'Diagnostic accepting discard sink: no HTTP/RPC/backpressure, not end-to-end capacity.'}));
